import { prisma } from '@/lib/prisma'
import { requireAuth } from '@/lib/auth'
import { redirect } from 'next/navigation'
import { formatDistanceToNow } from 'date-fns'
import { resolveActiveAirlineId } from '@/lib/active-airline'
import CreatePostForm from '@/components/airline/create-post-form'
import AirlineFeedPosts from '@/components/airline/airline-feed-posts'

export default async function AirlineFeedPage() {
  const session = await requireAuth()
  const selectedAirlineId = await resolveActiveAirlineId(session.user)
  if (!selectedAirlineId) redirect('/dashboard')

  const airline = await prisma.airline.findUnique({
    where: { id: selectedAirlineId },
  })
  if (!airline) redirect('/dashboard')

  const posts = await prisma.airlinePost.findMany({
    where: { airlineId: airline.id },
    orderBy: { createdAt: 'desc' },
    take: 50,
  })

  return (
    <div className="space-y-6 max-w-2xl">
      <h1 className="section-title">Airline Feed</h1>

      <CreatePostForm airlineId={airline.id} />

      {/* Posts Section - Client Component for Auto-Refresh */}
      <AirlineFeedPosts initialPosts={posts} airlineId={airline.id} />
    </div>
  )
}
